package com.example.starter.quarantine;

/**
 * 动物种类；决定检疫合格证有效期（自出证时刻起算，UTC）。
 */
public enum Species {

    /** 猪，有效期 24 小时。 */
    PIG(24),
    /** 牛，有效期 24 小时。 */
    CATTLE(24),
    /** 羊，有效期 24 小时。 */
    SHEEP(24),
    /** 禽，有效期 48 小时。 */
    POULTRY(48);

    private final int validityHours;

    Species(int validityHours) {
        this.validityHours = validityHours;
    }

    /**
     * 合格证有效期小时数。
     */
    public int validityHours() {
        return validityHours;
    }
}

package com.example.starter.quarantine;

/**
 * 检疫申报状态。
 */
public enum DeclarationStatus {

    /** 已申报，等待出证。 */
    DECLARED,
    /** 已驳回（如申报时养殖场已处于疫点封锁区）。 */
    REJECTED,
    /** 已出证。 */
    CERTIFIED
}

package com.example.starter.quarantine;

/**
 * 检疫合格证状态机：ISSUED → IN_TRANSIT → CLOSED；封锁/超时触发 VOIDED/EXPIRED。
 */
public enum CertificateStatus {

    /** 已出证未启运。 */
    ISSUED,
    /** 调运在途。 */
    IN_TRANSIT,
    /** 已作废（出证后未启运即遇疫点封锁）。 */
    VOIDED,
    /** 证失效（超过有效期终点仍未完成落地）。 */
    EXPIRED,
    /** 已结案（终态，累计落地数量等于证载数量）。 */
    CLOSED
}

package com.example.starter.quarantine;

/**
 * 落地报告处理结果。
 */
public enum ArrivalResult {

    /** 部分到达已受理，累计数量未达证载数量。 */
    ACCEPTED_PARTIAL,
    /** 到达已受理，累计数量恰等于证载数量，证结案。 */
    ACCEPTED_FINAL,
    /** 超过有效期终点，拒绝并将证标记为证失效。 */
    REJECTED_EXPIRED,
    /** 累计数量超过证载数量，整批拒绝。 */
    REJECTED_OVERFLOW,
    /** 证未处于在途状态（未启运），拒绝。 */
    REJECTED_NOT_IN_TRANSIT,
    /** 证已作废或已失效，拒绝。 */
    REJECTED_CERT_INVALID,
    /** 证已结案，迟到事件只记录不改状态。 */
    LATE_IGNORED
}

